import UIKit

/// Pixel-art bot mascot icons, embedded as base64 (mirrors apps/cline/webview/public/bot-icons/*.png,
/// downscaled to 240px) since this project's asset-catalog resource pipeline isn't picking up
/// bundled non-source files in this environment.
enum BotIcons {
    static let base64: [String] = [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    ]

    static func random() -> UIImage? {
        guard let b64 = base64.randomElement(), let data = Data(base64Encoded: b64) else { return nil }
        return UIImage(data: data)
    }
}